// Items of the server-template runtimes (Go templ, Twig, Latte, Jinja2) for r/<runtime>/, read from packages/<rt>/ui of the
// source monorepo (generated by xgen from the same specs as the TypeScript runtimes, parity-gated there against React's DOM).
//
// One item per name of the TypeScript runtimes when the runtime has it (slot, the React asChild primitive, has no template):
//   primitive          -> ui/<name>/* (template, *.variants.json; templ: *_gen.go and the Lucide glyph table)
//   block / component  -> blocks/<name><ext> (one template; the package keeps every organism in blocks/)
//   utils              -> the helpers + package manifest (templ: utils/*.go, go.mod, go.sum; Twig/Latte: php/*.php, composer.json;
//                         Jinja2: py/ui8kit_jinja/*.py, pyproject.toml, requirements.txt)
//   presets (lib)      -> blocks/presets/*.json, blocks/recipes/*.json (templ: + blocks/embed.go, which embeds them for package blocks)
// File targets are relative to the template root (Go module root / Twig, Latte and Jinja2 loader root): install with
// `--dir <root>` and the include paths ('ui/box/box.html.twig', 'blocks/media-frame.latte') and Go imports resolve unchanged.
// registryDependencies come from the template references (includes, Go imports, same-package templ symbols, recipe/preset reads).
// npm `dependencies` stay empty: the toolchain requirements (templ, twig/twig, latte/latte, Jinja2) are in the utils manifest files.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";

export const TEMPLATE_RUNTIMES = ["templ", "twig", "latte", "jinja2"] as const;
export type TemplateRuntime = (typeof TEMPLATE_RUNTIMES)[number];

export const TEMPLATE_EXT: Record<TemplateRuntime, string> = { templ: ".templ", twig: ".html.twig", latte: ".latte", jinja2: ".html.j2" };

export type Kind = "utils" | "lib" | "primitive" | "component" | "block";
export interface TemplateItemSource {
  name: string;
  kind: Kind;
  files: { path: string; content: string }[];
  registryDependencies: string[];
}

const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const GO_MODULE_RE = /^module\s+(\S+)/m;

/** Per-name kind from the TypeScript runtimes; returns the template items of one runtime (sorted by name). */
export function buildTemplateRuntime(src: string, rt: TemplateRuntime, kinds: Map<string, Kind>): { items: TemplateItemSource[]; problems: string[] } {
  const root = path.join(src, "packages", rt, "ui");
  if (!existsSync(root)) throw new Error(`missing ${root}`);
  const ext = TEMPLATE_EXT[rt];
  const read = (rel: string) => readFileSync(path.join(root, rel), "utf8");
  const ls = (rel: string, ok: (f: string) => boolean = () => true) =>
    existsSync(path.join(root, rel)) ? readdirSync(path.join(root, rel)).filter(ok).sort(cmp).map((f) => `${rel}/${f}`) : [];
  const problems: string[] = [];

  const utilsFiles =
    rt === "templ" ? [...ls("utils", (f) => f.endsWith(".go") && !f.endsWith("_test.go")), "go.mod", "go.sum"]
    : rt === "jinja2" ? [...ls("py/ui8kit_jinja", (f) => f.endsWith(".py")), "pyproject.toml", "requirements.txt"]
    : [...ls("php", (f) => f.endsWith(".php")), "composer.json"];
  const presetFiles = [
    ...(rt === "templ" ? ["blocks/embed.go"] : []),
    ...ls("blocks/presets", (f) => f.endsWith(".json")),
    ...ls("blocks/recipes", (f) => f.endsWith(".json")),
  ];

  const sources = new Map<string, { kind: Kind; files: string[] }>();
  sources.set("utils", { kind: "utils", files: utilsFiles });
  sources.set("presets", { kind: "lib", files: presetFiles });
  for (const [name, kind] of [...kinds].sort((a, b) => cmp(a[0], b[0]))) {
    if (kind === "utils" || kind === "lib") continue;
    if (kind === "primitive") {
      const files = ls(`ui/${name}`);
      if (files.length) sources.set(name, { kind, files });
      continue;
    }
    const f = `blocks/${name}${ext}`;
    if (existsSync(path.join(root, f))) sources.set(name, { kind, files: [f] });
    else problems.push(`${rt}: no ${f}`);
  }
  // template files the TypeScript runtimes do not have (would be unreachable): report
  for (const f of ls("blocks", (x) => x.endsWith(ext))) {
    const n = path.basename(f, ext);
    if (!sources.has(n)) problems.push(`${rt}: ${f} has no item in the TypeScript runtimes`);
  }

  // templ: package blocks is one Go package; map every top-level symbol to the item that declares it
  const goModule = rt === "templ" ? read("go.mod").match(GO_MODULE_RE)?.[1] ?? "" : "";
  const symbolOwner = new Map<string, string>();
  if (rt === "templ") {
    for (const [name, s] of sources) {
      if (s.kind !== "block" && s.kind !== "component" && name !== "presets") continue;
      for (const f of s.files.filter((x) => x.endsWith(".templ") || x.endsWith(".go"))) {
        for (const m of read(f).matchAll(/^(?:templ|func|type|var|const)\s+([A-Za-z_]\w*)/gm)) symbolOwner.set(m[1]!, name);
      }
    }
  }

  const items: TemplateItemSource[] = [];
  for (const [name, s] of [...sources].sort((a, b) => cmp(a[0], b[0]))) {
    const files = s.files.map((p) => ({ path: p, content: read(p) }));
    const deps = new Set<string>();
    // utils: no dependencies (the helpers read ui/lucide-icon/lucide-icons.json lazily, only for the lucide-icon template)
    for (const f of s.kind === "utils" ? [] : files) {
      const c = f.content;
      if (rt === "templ") {
        if (!/\.(templ|go)$/.test(f.path)) continue;
        for (const m of c.matchAll(/"([^"\s]+)"/g)) {
          const spec = m[1]!;
          if (!goModule || !spec.startsWith(goModule + "/")) continue;
          const rel = spec.slice(goModule.length + 1);
          if (rel === "utils") deps.add("utils");
          else if (rel.startsWith("ui/")) deps.add(rel.slice(3));
          else problems.push(`${rt}/${name}: unknown module import ${spec}`);
        }
        if (s.kind === "block" || s.kind === "component") {
          const body = c.replace(/\/\/.*$/gm, "").replace(/"(?:[^"\\\n]|\\.)*"/g, '""').replace(/`[^`]*`/g, "``");
          // a use is a call or literal (`@MediaFrame(`, `CartTable(`, `CartTableProps{`), a Props type, or a package variable
          // (recipeAvatar, presetDefaults); struct keys and field names (`Field:`, `Avatar any`) are not uses
          for (const m of body.matchAll(/(?<![.\w])([A-Za-z_]\w*)\b(\s*[({])?/g)) {
            const id = m[1]!;
            const owner = symbolOwner.get(id);
            if (!owner || owner === name) continue;
            if (m[2] || id.endsWith("Props") || /^[a-z]/.test(id)) deps.add(owner);
          }
        }
      } else {
        for (const m of c.matchAll(/['"](blocks|ui)\/([\w.-]+)(\/[\w.-]+)?['"]/g)) {
          const [, top, seg, rest] = m;
          if (top === "ui") deps.add(seg!);
          else if (seg === "recipes" || seg === "presets") deps.add("presets");
          else if (!rest) deps.add(seg!.endsWith(ext) ? seg!.slice(0, -ext.length) : seg!);
        }
      }
    }
    if (s.kind !== "utils") deps.add("utils"); // template helpers (ui_* functions, uiutils) are used by every template
    deps.delete(name);
    for (const d of deps) if (!sources.has(d)) problems.push(`${rt}/${name}: dependency ${d} is not an item`);
    items.push({ name, kind: s.kind, files, registryDependencies: [...deps].filter((d) => sources.has(d)).sort(cmp) });
  }
  return { items, problems };
}
